#include <item/WorldUtilityRuntime.hpp>
void StatefulUtilityCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources)
{
    using namespace auriga::item;Check(sources.size()==7,"seven actual source world utilities");CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);
    Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned stateful utility SQL connection");
    auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-stateful-utility-worker").has_value(),"actual stateful utility worker starts");
    unsigned serial=0,packets=0;bool replay=false;
    const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0xF4,static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
    const auto apply=[&](persistence::LoadedItemOwner& state,const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(state.fence.owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"world utility queued");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->write && got->state,"world utility persisted and reloaded");replay=got->write->replay;state=*got->state;};
    const auto relog=[&](persistence::LoadedItemOwner& state){const auto saved=state;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,state.fence.owner).value();state=persistence::LoadItemOwner(sql,*catalog,state.fence.owner,generation).value();Check(state.items==saved.items && state.recovery==saved.recovery,"counter, stamp, UTC deadline and pending warp survive SQL relog");};
    const auto acknowledge=[&](persistence::LoadedItemOwner& state){if(!state.recovery.worldWarp)return;auto after=state.recovery;after.worldWarp.reset();++after.revision;ItemCommit c;c.operationId=op();c.kind=ItemOperationKind::Service;c.catalogRevision=catalog->Revision();c.catalogHash=catalog->ContentHash();c.owners={state.fence};c.outcomeCode=0x2003;c.result={'R','T','M',1};c.recovery=ItemRecoveryChange{state.fence.owner,state.recovery,after,0};apply(state,c);Check(!state.recovery.worldWarp,"arrival acknowledgment clears only durable world intent");};
    const std::uint64_t now=1794697200000ULL;
    for(unsigned n=0;n<sources.size();++n){const ItemOwner owner{ItemOwnerKind::Character,17000u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"world owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();
        const auto ids=runtime::PeekInstanceIds(2);runtime::SpendInstanceIds(2);auto spec=sources[n].grant;const bool detector=spec.key.Category()==ItemCategory::Tool;spec.count=(detector || RecallItemMode(*catalog,spec.key)!=RecallMode::None) ? 1 : 2;
        apply(state,MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,std::span(ids).first(1)).value());auto identity=ids[0];
        WorldUtilityFacts facts;facts.character.level=255;facts.position={21,10000,10000};facts.empire=2;facts.hp=facts.maximumHp=1000;facts.admitted=facts.alive=facts.mapLoaded=facts.warpReady=facts.summonZoneAllowed=facts.savedDestinationAvailable=facts.campfireSpotAllowed=facts.campfirePrepared=true;facts.town=RecallPosition{21,30000,30000};facts.stoneVid=77;facts.stoneRange=2;facts.stoneBearing=90;
        const auto* use=catalog->FindUsePolicy(catalog->Find(spec.key)->base.usePolicy);while(!(use->allowedClasses&(1u<<facts.character.characterClass)))++facts.character.characterClass;while(!(use->allowedSexes&(1u<<facts.character.sex)))++facts.character.sex;
        const auto write=[&](const std::string& phase){const auto file=[&](const char* kind,const auto& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){const auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"actual stateful utility wire state exported");};file("inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file("details",EncodeTypedItemDetails(*catalog,state.items).value());++packets;};
        write("ready");
        if(detector){for(unsigned step=1;step<=6;++step){const auto plan=MakeWorldUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,state.recovery,identity,facts,0,now).value();Check(plan.quote.remainingUses==6-step,"original detector decrements one use");apply(state,*plan.commit);const auto saved=state;apply(state,*plan.commit);Check(replay && state.items==saved.items && state.recovery==saved.recovery,"detector operation receipt never spends twice");relog(state);write("use"+std::to_string(step));}Check(state.items.empty(),"actual detector final use destroys instance");}
        else if(RecallItemMode(*catalog,spec.key)!=RecallMode::None){const auto first=MakeWorldUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,state.recovery,identity,facts,0,now,ids[1]).value();Check(!first.quote.split,"actual original nonstackable scroll keeps its instance");apply(state,*first.commit);relog(state);Check(state.items.size()==1,"actual stamped nonstackable scroll reloads");write("stamped");
            if(first.quote.destination){Check(state.recovery.worldWarp && state.recovery.worldWarp->destination==*facts.town && state.recovery.worldWarp->hpCeiling==700,"lost callback retains exact town destination and paid HP ceiling");const auto saved=state;apply(state,*first.commit);Check(replay && state.recovery==saved.recovery,"town warp receipt replay leaves intent and source unchanged");acknowledge(state);}
            facts.position.x=40000;const auto back=MakeWorldUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,state.recovery,identity,facts,0,now).value();Check(back.quote.consume && back.quote.destination==RecallPosition{21,10000,10000},"actual stamped scroll recalls exact source location");apply(state,*back.commit);relog(state);Check(state.items.empty() && state.recovery.worldWarp && state.recovery.worldWarp->destination==*back.quote.destination,"spent scroll and pending return persist atomically");write("returned");acknowledge(state);relog(state);write("acknowledged");}
        else{auto denied=facts;denied.campfirePrepared=false;Check(!MakeWorldUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,state.recovery,identity,denied,0,now),"failed spawn preparation preserves campfire");const auto first=MakeWorldUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,state.recovery,identity,facts,0,now).value();apply(state,*first.commit);const auto saved=state;apply(state,*first.commit);Check(replay && state.items==saved.items && state.recovery==saved.recovery,"campfire receipt is idempotent");relog(state);write("burning");Check(WorldUtilityCooldownRemaining(*catalog,state.recovery,now)==60000,"UTC reuse survives SQL relog");Check(!MakeWorldUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,state.recovery,identity,facts,0,now+59999),"campfire cannot bypass cooldown by relogging");const auto next=MakeWorldUtilityCommit(*catalog,op(),state.fence,state.storages,state.items,state.recovery,identity,facts,0,now+60000).value();apply(state,*next.commit);relog(state);write("expired");}
    }
    store.Stop();std::cout<<"SOURCE_STATEFUL_UTILITY_WORKER=SUCCESS sources=7 packets="<<packets<<" checks="<<checks<<std::endl;
}
